import 'dart:convert';
import 'dart:math' as math;
import 'dart:typed_data';

import 'package:haftnard/core/ai/bearoff_data.dart';

/// Exact one-sided bear-off: for every way to place up to 15 checkers on
/// the home points 1–6, the expected number of rolls to bear them all off
/// with perfect play. 54,264 positions, generated by `tool/gen_bearoff.dart`
/// (stored as Uint16 = rolls × [scale]).
abstract final class BearOff {
  static const int points = 6;
  static const int maxCheckers = 15;
  static const double scale = 4096;

  /// Positions with up to 15 checkers on 6 points: C(21, 6).
  static const int size = 54264;

  static Uint16List? _table;

  static Uint16List get _data =>
      _table ??= Uint16List.view(base64Decode(kBearOffData).buffer);

  /// Ways to put at most [total] checkers on [slots] points: C(total+slots,
  /// slots).
  static int _count(int slots, int total) {
    if (total < 0) return 0;
    var r = 1;
    for (var i = 1; i <= slots; i++) {
      r = r * (total + i) ~/ i;
    }
    return r;
  }

  /// Rank of `c[1..6]` (counts per home point, at most 15 in all).
  static int index(List<int> c) {
    var rank = 0;
    var budget = maxCheckers;
    for (var p = 1; p <= points; p++) {
      final v = c[p];
      for (var x = 0; x < v; x++) {
        rank += _count(points - p, budget - x);
      }
      budget -= v;
    }
    return rank;
  }

  /// Every home-board position, in rank order (for the generator/tests).
  static List<List<int>> allPositions() {
    final out = <List<int>>[];
    void rec(List<int> c, int p, int budget) {
      if (p > points) {
        out.add(List.of(c));
        return;
      }
      for (var v = 0; v <= budget; v++) {
        c[p] = v;
        rec(c, p + 1, budget - v);
      }
      c[p] = 0;
    }

    rec(List.filled(points + 1, 0), 1, maxCheckers);
    return out;
  }

  /// Whether every checker of [side] (26-slot relative array: 0 = off,
  /// 25 = bar) is home or off.
  static bool isHome(List<int> side) {
    for (var i = 7; i <= 25; i++) {
      if (side[i] != 0) return false;
    }
    return true;
  }

  /// Expected rolls to bear off [side] (all home), with perfect play.
  static double expectedRolls(List<int> side) => _data[index(side)] / scale;

  /// Win chance for the side that just moved ([mine]) in a pure bear-off
  /// race where the opponent ([theirs]) rolls next.
  static double winProb(List<int> mine, List<int> theirs) {
    final em = expectedRolls(mine);
    final et = expectedRolls(theirs);
    // Normal approximation of "I need fewer rolls than they do, and they
    // roll first"; the spread grows with the race length.
    final z = (et - em - 0.5) / (0.55 * math.sqrt(em + et) + 0.35);
    return _phi(z).clamp(0.0, 1.0);
  }

  static double _phi(double z) {
    // Abramowitz–Stegun erf approximation.
    final t = 1 / (1 + 0.3275911 * z.abs() / math.sqrt2);
    final y =
        1 -
        (((((1.061405429 * t - 1.453152027) * t) + 1.421413741) * t -
                        0.284496736) *
                    t +
                0.254829592) *
            t *
            math.exp(-z * z / 2);
    return z >= 0 ? (1 + y) / 2 : (1 - y) / 2;
  }

  // ------------------------------------------------------------ generator

  /// Positions reachable by playing one die [d] from `c[1..6]`.
  static Iterable<List<int>> _oneDie(List<int> c, int d) sync* {
    var highest = 0;
    for (var p = points; p >= 1; p--) {
      if (c[p] > 0) {
        highest = p;
        break;
      }
    }
    if (highest == 0) {
      yield c;
      return;
    }
    for (var p = 1; p <= points; p++) {
      if (c[p] == 0) continue;
      if (p > d) {
        final n = List.of(c);
        n[p]--;
        n[p - d]++;
        yield n;
      } else if (p == d || (p == highest && d > highest)) {
        final n = List.of(c);
        n[p]--;
        yield n;
      }
    }
  }

  /// Computes the table from scratch (used by the generator and tests).
  static Float64List compute({int maxTotal = maxCheckers}) {
    final positions = allPositions()
      ..removeWhere((c) => c.fold(0, (a, b) => a + b) > maxTotal);
    int pips(List<int> c) {
      var s = 0;
      for (var p = 1; p <= points; p++) {
        s += c[p] * p;
      }
      return s;
    }

    positions.sort((a, b) => pips(a).compareTo(pips(b)));
    final e = Float64List(size);
    final done = Uint8List(size);
    for (final c in positions) {
      final i = index(c);
      if (pips(c) == 0) {
        done[i] = 1;
        continue;
      }
      var sum = 0.0;
      for (var a = 1; a <= 6; a++) {
        for (var b = a; b <= 6; b++) {
          final w = a == b ? 1 : 2;
          final dice = a == b ? [a, a, a, a] : [a, b];
          final orders = a == b
              ? [dice]
              : [
                  dice,
                  [b, a],
                ];
          var best = double.infinity;
          for (final order in orders) {
            var frontier = <List<int>>[c];
            for (final d in order) {
              final next = <int, List<int>>{};
              for (final f in frontier) {
                for (final n in _oneDie(f, d)) {
                  next[index(n)] = n;
                }
              }
              frontier = next.values.toList();
            }
            for (final f in frontier) {
              final j = index(f);
              assert(done[j] == 1 || pips(f) == 0, 'not computed yet');
              if (e[j] < best) best = e[j];
            }
          }
          sum += w * best;
        }
      }
      e[i] = 1 + sum / 36;
      done[i] = 1;
    }
    return e;
  }

  /// Encodes [e] the way [kBearOffData] stores it.
  static String encode(Float64List e) {
    final u = Uint16List(size);
    for (var i = 0; i < size; i++) {
      u[i] = (e[i] * scale).round().clamp(0, 65535);
    }
    return base64Encode(u.buffer.asUint8List());
  }
}
